class Pipeline:
    def __init__(self, data):
        self.data = data

    def where(self, pred):
        return Pipeline([x for x in self.data if pred(x)])

    def map(self, func):
        return Pipeline([func(x) for x in self.data])

    def sum(self):
        return sum(self.data)

    def len(self):
        return len(self.data)

    def count(self, pred):
        return len([x for x in self.data if pred(x)])

def main():
    nums = [3, 8, 1, 12, 5, 9]
    p = Pipeline(nums)

    filtered = p.where(lambda x: x > 5)

    print(filtered.len())
    print(filtered.sum())
    print(filtered.map(lambda x: x * 2).sum())

if __name__ == "__main__":
    main()

